{
  "schemaVersion": "0.2",
  "slug": "pipeline-view",
  "name": "PipelineView",
  "family": "G",
  "status": "experimental",
  "purpose": "Shows CI/CD stages as an ordered flow with per-stage status.",
  "scenarios": [
    "Build pipeline status",
    "Release train stages",
    "ETL job overview"
  ],
  "props": {
    "stages": {
      "type": "string",
      "required": true,
      "description": "Array of { id, name, status } stages in order."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible label for the pipeline region."
    },
    "statusLabels": {
      "type": "string",
      "required": false,
      "description": "Localized status label map."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Pipeline rendered."
    },
    {
      "name": "empty",
      "description": "No stages provided."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "app-shell",
      "card"
    ],
    "allowedChildren": [
      "badge",
      "button"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not reorder stages by status; keep pipeline order.",
    "Do not show duration without a real measurement source."
  ],
  "a11y": {
    "role": "list",
    "keyboard": [],
    "focus": "Stage actions are buttons in order.",
    "labeling": "Stage name plus status text labels each stage.",
    "wcag": [
      "1.3.1",
      "1.4.1"
    ]
  },
  "responsive": {
    "strategy": "Stages scroll horizontally on compact.",
    "breakpoints": {
      "compact": "Horizontal scroll.",
      "medium": "Inline row.",
      "large": "Inline row."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "pipeline-view",
    "states": [
      "default",
      "empty",
      "pending",
      "running",
      "success",
      "failed"
    ],
    "intents": [
      "show-progress"
    ]
  }
}

{
  "pipeline-view": {
    "label": "流水线",
    "statusPending": "等待中",
    "statusRunning": "运行中",
    "statusSuccess": "已成功",
    "statusFailed": "已失败"
  }
}

import './styles.css'

export interface PipelineStage {
  id: string
  name: string
  status: 'pending' | 'running' | 'success' | 'failed'
}

export interface PipelineViewProps {
  stages: PipelineStage[]
  label: string
  statusLabels?: Partial<Record<PipelineStage['status'], string>>
  className?: string
}

const DEFAULT_STATUS_LABELS: Record<PipelineStage['status'], string> = {
  pending: 'Pending',
  running: 'Running',
  success: 'Succeeded',
  failed: 'Failed',
}

export function PipelineView({ stages, label, statusLabels, className }: PipelineViewProps) {
  const classes = ['cu-pipeline-view', className].filter(Boolean).join(' ')
  const labels = { ...DEFAULT_STATUS_LABELS, ...statusLabels }

  return (
    <section
      className={classes}
      aria-label={label}
      data-ai-role="pipeline-view" data-ai-intent="show-progress"
      data-ai-state={stages.length === 0 ? 'empty' : 'default'}
    >
      <ol className="cu-pipeline-view__stages">
        {stages.map((stage) => (
          <li key={stage.id} className={'cu-pipeline-view__stage cu-pipeline-view__stage--' + stage.status}>
            <span className="cu-pipeline-view__name">{stage.name}</span>
            <span className="cu-pipeline-view__status">{labels[stage.status]}</span>
          </li>
        ))}
      </ol>
    </section>
  )
}

.cu-pipeline-view {
  display: block;
  overflow-x: auto;
  color: var(--cu-color-fg-default);
}

.cu-pipeline-view__stages {
  display: flex;
  align-items: stretch;
  gap: var(--cu-space-2);
  list-style: none;
  margin: 0;
  padding: 0;
}

.cu-pipeline-view__stage {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: calc(var(--cu-space-1) / 2);
  min-inline-size: calc(var(--cu-space-3) * 12);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
}

.cu-pipeline-view__stage + .cu-pipeline-view__stage::before {
  content: '';
  position: absolute;
  inset-inline-start: calc(-1 * var(--cu-space-2) - 1px);
  inset-block-start: 50%;
  inline-size: var(--cu-space-2);
  border-block-start: 2px solid var(--cu-color-border-default);
}

.cu-pipeline-view__stage--running {
  border-color: var(--cu-color-palette-brand);
}

.cu-pipeline-view__stage--success {
  border-color: color-mix(in srgb, var(--cu-color-palette-brand) 50%, green);
}

.cu-pipeline-view__stage--failed {
  border-color: color-mix(in srgb, var(--cu-color-palette-brand) 50%, red);
}

.cu-pipeline-view__name {
  font-weight: 600;
}

.cu-pipeline-view__status {
  font-size: 0.875em;
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}
